-- Developed by Pughal Jeyaprakash
create extension if not exists pgcrypto;
drop trigger if exists check_domain on auth.users; drop function if exists public.enforce_college_domain();
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text,email text not null,avatar_url text,created_at timestamptz default now());
create table if not exists public.items(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id) on delete cascade,type text not null check(type in('lost','found')),title text not null check(char_length(title)<=100),description text check(char_length(description)<=1000),category text not null,location text,item_date date,image_url text,status text not null default 'open' check(status in('open','returned')),created_at timestamptz default now());
create index if not exists items_created_idx on public.items(created_at desc); create index if not exists items_status_idx on public.items(status);
create table if not exists public.item_contacts(item_id uuid primary key references public.items(id) on delete cascade,contact text not null check(char_length(contact)<=120));
create table if not exists public.returns(id uuid primary key default gen_random_uuid(),item_id uuid not null unique references public.items(id) on delete cascade,recorded_by uuid not null references public.profiles(id),returned_to_name text not null,returned_to_contact text,returned_on date not null default current_date,handover_location text,verification_notes text,created_at timestamptz default now());
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,email,full_name,avatar_url) values(new.id,new.email,new.raw_user_meta_data->>'full_name',new.raw_user_meta_data->>'avatar_url') on conflict(id) do nothing; return new; end; $$;
drop trigger if exists on_auth_user_created on auth.users; create trigger on_auth_user_created after insert on auth.users for each row execute function public.handle_new_user();
create or replace function public.limit_daily_posts() returns trigger language plpgsql security definer set search_path=public as $$ begin if(select count(*) from public.items where user_id=new.user_id and created_at>now()-interval '1 day')>=10 then raise exception 'Daily post limit reached'; end if; return new; end; $$;
drop trigger if exists items_daily_limit on public.items; create trigger items_daily_limit before insert on public.items for each row execute function public.limit_daily_posts();
create or replace function public.mark_item_returned() returns trigger language plpgsql security definer set search_path=public as $$ begin update public.items set status='returned' where id=new.item_id; return new; end; $$;
drop trigger if exists on_return_created on public.returns; create trigger on_return_created after insert on public.returns for each row execute function public.mark_item_returned();
alter table public.profiles enable row level security; alter table public.items enable row level security; alter table public.item_contacts enable row level security; alter table public.returns enable row level security;
drop policy if exists "profiles readable by signed-in" on public.profiles; create policy "profiles readable by signed-in" on public.profiles for select to authenticated using(true);
drop policy if exists "items readable by everyone" on public.items; create policy "items readable by everyone" on public.items for select to anon,authenticated using(true);
drop policy if exists "users insert own items" on public.items; create policy "users insert own items" on public.items for insert to authenticated with check(user_id=auth.uid());
drop policy if exists "owners update own items" on public.items; create policy "owners update own items" on public.items for update to authenticated using(user_id=auth.uid());
drop policy if exists "owners delete own items" on public.items; create policy "owners delete own items" on public.items for delete to authenticated using(user_id=auth.uid());
drop policy if exists "contacts readable by signed-in" on public.item_contacts; create policy "contacts readable by signed-in" on public.item_contacts for select to authenticated using(true);
drop policy if exists "owners add contact" on public.item_contacts; create policy "owners add contact" on public.item_contacts for insert to authenticated with check(exists(select 1 from public.items i where i.id=item_id and i.user_id=auth.uid()));
drop policy if exists "owners update contact" on public.item_contacts; create policy "owners update contact" on public.item_contacts for update to authenticated using(exists(select 1 from public.items i where i.id=item_id and i.user_id=auth.uid()));
drop policy if exists "owners read return details" on public.returns; create policy "owners read return details" on public.returns for select to authenticated using(exists(select 1 from public.items i where i.id=item_id and i.user_id=auth.uid()));
drop policy if exists "owners add return details" on public.returns; create policy "owners add return details" on public.returns for insert to authenticated with check(recorded_by=auth.uid() and exists(select 1 from public.items i where i.id=item_id and i.user_id=auth.uid()));
insert into storage.buckets(id,name,public) values('item-images','item-images',true) on conflict(id) do update set public=true;
drop policy if exists "public read item images" on storage.objects; create policy "public read item images" on storage.objects for select using(bucket_id='item-images');
drop policy if exists "authenticated upload item images" on storage.objects; create policy "authenticated upload item images" on storage.objects for insert to authenticated with check(bucket_id='item-images' and (storage.foldername(name))[1]=auth.uid()::text);
drop policy if exists "owners delete item images" on storage.objects; create policy "owners delete item images" on storage.objects for delete to authenticated using(bucket_id='item-images' and owner_id=auth.uid()::text);
